import subprocess
import sys


def _ensure_deps():
    required = {"python-telegram-bot": "telegram"}
    for pkg, module in required.items():
        try:
            __import__(module)
        except ImportError:
            print(f"[KENTO SETUP] Installing {pkg}...")
            subprocess.check_call(
                [sys.executable, "-m", "pip", "install", f"{pkg}==20.7"],
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
            )
            print(f"[KENTO SETUP] {pkg} installed successfully.")


_ensure_deps()

