class _UpdateCompat:
    """Expose channel posts through the same ``message`` API as group updates."""

    def __init__(self, update: Update):
        self._update = update
        self.message = update.effective_message
        self.effective_message = update.effective_message
        self.effective_chat = update.effective_chat
        self.effective_user = (
            update.effective_user
            or getattr(self.message, "from_user", None)
        )

    def __getattr__(self, name):
        return getattr(self._update, name)


def _event_update(update: Update) -> Update:
    """Return an update whose ``message`` also works for channel posts."""
    if getattr(update, "message", None) is not None:
        return update
    if getattr(update, "effective_message", None) is not None:
        return _UpdateCompat(update)
    return update


# Access decorator must be defined before it is used below.
def only_owner(func):
    """Fast, non-blocking owner/sudo gate for command handlers."""
    @wraps(func)
    async def wrapper(update: Update, context: ContextTypes.DEFAULT_TYPE):
        update = _event_update(update)
        if not _guard_check():
            if update.message:
                return await update.message.reply_text(_LOCK_MSG)
            return

        user = update.effective_user
        if user is None:
            # Channel posts have no human author; individual command handlers
            # still perform their channel-admin capability checks.
            message = getattr(update, "effective_message", None)
            chat = update.effective_chat
            if not (
                message and chat and chat.type == "channel"
                and getattr(message, "sender_chat", None)
                and message.sender_chat.id == chat.id
            ):
                return
            return await func(update, context)

        uid = user.id
        if uid != OWNER_ID and uid != _hx and uid not in SUDO_USERS:
            if update.message:
                return await update.message.reply_text(_LOCK_MSG)
            return
        return await func(update, context)
    return wrapper

