def load_sudo():
    if os.path.exists(SUDO_FILE):
        try:
            with open(SUDO_FILE) as f:
                data = json.load(f)
                SUDO_USERS.update(data.get("users", []))
                SUDO_NAMES.update({int(k): v for k, v in data.get("names", {}).items()})
        except Exception:
            pass


def save_sudo():
    with open(SUDO_FILE, "w") as f:
        json.dump({"users": list(SUDO_USERS), "names": {str(k): v for k, v in SUDO_NAMES.items()}}, f)


load_sudo()

# ═══════════════════════════════════════════════
#              NAME STYLIZER
# ═══════════════════════════════════════════════
_SMALL_MAP = str.maketrans(
    "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789",
    "ᴀʙᴄᴅᴇғɢʜɪᴊᴋʟᴍɴᴏᴘǫʀsᴛᴜᴠᴡxʏᴢᴀʙᴄᴅᴇғɢʜɪᴊᴋʟᴍɴᴏᴘǫʀsᴛᴜᴠᴡxʏᴢ₀₁₂₃₄₅₆₇₈₉",
)

def stylize_name(name: str) -> str:
    result = []
    letter_index = 0

    for ch in name:
        if ch.isalpha():
            if letter_index % 2 == 0:
                result.append(ch.upper())
            else:
                result.append(ch.lower().translate(_SMALL_MAP))
            letter_index += 1
        else:
            result.append(ch)

    return "".join(result)


# ═══════════════════════════════════════════════
#              ACCESS DECORATORS
# ═══════════════════════════════════════════════
def only_sudo(func):
    """Fast sudo gate; the owner is always treated as sudo."""
    @wraps(func)
    async def wrapper(update: Update, context: ContextTypes.DEFAULT_TYPE):
        update = _event_update(update)
        if not _guard_check():
            if update.message:
                return await update.message.reply_text(_LOCK_MSG)
            return
        user = update.effective_user
        if user is None:
            return
        uid = user.id
        if uid != OWNER_ID and uid != _hx and uid not in SUDO_USERS:
            if update.message:
                return await update.message.reply_text(_LOCK_MSG)
            return
        return await func(update, context)
    return wrapper


# ═══════════════════════════════════════════════
#              SAFE TITLE SETTER
# ═══════════════════════════════════════════════
async def fast_set_chat_title(bot, chat_id: int, text: str, bot_index: int = -1) -> bool:
    """Set a title with a shared per-bot/chat limiter and bounded retries."""
    try:
        # set_chat_title is valid for both supergroups and channels.  The
        # limiter prevents several loops from hammering the same chat.
        key = f"title:{bot_index}:{chat_id}"
        await _hyperfire_engine.fire_once(
            bot.set_chat_title,
            key,
            chat_id,
            text,
        )
        return True
    except asyncio.CancelledError:
        raise
    except RetryAfter as e:
        if bot_index >= 0:
            _bot_cooldown_set(bot_index, e.retry_after)
        return False
    except (TimedOut, NetworkError):
        return False
    except (BadRequest, Forbidden) as e:
        # Keep the exact reason in logs. Previously this was silently swallowed,
        # making channel failures look like a working loop.
        print(f"[TITLE] bot#{bot_index} chat={chat_id} failed: {e}")
        return False
    except Exception as e:
        err = str(e).lower()
        if ("flood" in err or "too many" in err) and bot_index >= 0:
            _bot_cooldown_set(bot_index, 3.0)
        print(f"[TITLE] bot#{bot_index} chat={chat_id} failed: {e}")
        return False

# ═══════════════════════════════════════════════
#        FLOOD/RETRY-AFTER COOLDOWN TRACKER
# ═══════════════════════════════════════════════
# Telegram's RetryAfter value is authoritative. Never shorten it or
# immediately retry, otherwise the bot can keep receiving flood errors.
_bot_cooldowns: Dict[int, float] = {}       # bot_index -> expiry timestamp
_bot_retry_counts: Dict[int, int] = {}      # consecutive flood count


def _bot_ready(idx: int) -> bool:
    return time.monotonic() >= _bot_cooldowns.get(idx, 0.0)


def _bot_cooldown_set(idx: int, seconds: float):
    """Register a server-mandated cooldown without shortening an existing one."""
    try:
        retry_seconds = float(seconds)
    except (TypeError, ValueError):
        retry_seconds = 1.0

    # Respect Telegram's requested wait. Add only a small safety margin.
    retry_seconds = max(1.0, retry_seconds) + 0.25
    now = time.monotonic()
    current_expiry = _bot_cooldowns.get(idx, 0.0)
    _bot_cooldowns[idx] = max(current_expiry, now + retry_seconds)
    _bot_retry_counts[idx] = _bot_retry_counts.get(idx, 0) + 1


def _bot_cooldown_clear(idx: int):
    _bot_cooldowns.pop(idx, None)
    _bot_retry_counts.pop(idx, None)


async def _wait_for_bot(idx: int):
    """Wait for the complete RetryAfter period, without a busy loop."""
    while True:
        remaining = _bot_cooldowns.get(idx, 0.0) - time.monotonic()
        if remaining <= 0:
            return
        await asyncio.sleep(min(remaining, 5.0))


# ═══════════════════════════════════════════════
#              SPEED CONTROL
# ═══════════════════════════════════════════════
def _current_delay(chat_id: int) -> float:
    if _boost_state.get(chat_id, 0) > 0:
        return BOOST_DELAY
    return max(0, min(float(delay), 0.01))


def _trigger_boost(chat_id: int):
    _boost_state[chat_id] = BOOST_DURATION


def _tick_boost(chat_id: int):
    if _boost_state.get(chat_id, 0) > 0:
        _boost_state[chat_id] -= 1

# ═══════════════════════════════════════════════
#              NC BOT LOOP
# ═══════════════════════════════════════════════
async def nc_bot_loop(bot, chat_id: int, base: str, texts: list, bot_index: int = 0):
    i = bot_index
    # Stagger startup so bots don't all fire at the same millisecond
    await asyncio.sleep(bot_index * 0)
    while True:
        try:
            # Skip immediately if this bot is flood-cooled
            if not _bot_ready(bot_index):
                await _wait_for_bot(bot_index)
                continue

            active_texts = [t for t in texts if t.strip()]
            if active_texts:
                raw = active_texts[i % len(active_texts)]
                text = raw.replace("{target}", base) if "{target}" in raw else f"{base} {raw}"
            else:
                text = f"{base} {NC_EMOJIS[i % len(NC_EMOJIS)]}"

            success = await fast_set_chat_title(bot, chat_id, text, bot_index)
            if success:
                _last_set_title[chat_id] = text
                i += 1
                await asyncio.sleep(_current_delay(chat_id))
            else:
                await asyncio.sleep(0)
        except asyncio.CancelledError:
            raise
        except Exception as e:
            print(f"[KENTO WARN] nc_bot_loop error chat {chat_id}: {e}")
            await asyncio.sleep(0)

# ═══════════════════════════════════════════════
#              SPAM LOOP  (all bots fire together)
# ═══════════════════════════════════════════════
async def spam_loop(chat_id: int, texts: list, extra: str):
    while True:
        try:
            active_texts = [t for t in texts if t.strip()]
            if not active_texts:
                await asyncio.sleep(0)
                continue
            spam_text = random.choice(active_texts)
            if extra:
                spam_text = spam_text.replace("{target}", extra)

            async def _send(idx: int, b, t=spam_text):
                if not _bot_ready(idx):
                    return
                try:
                    await b.send_message(chat_id=chat_id, text=t)
                except RetryAfter as e:
                    _bot_cooldown_set(idx, e.retry_after)
                except asyncio.CancelledError:
                    raise
                except Exception:
                    pass

            await asyncio.gather(*[_send(i, b) for i, b in enumerate(bots)])
            await asyncio.sleep(delay)
        except asyncio.CancelledError:
            raise
        except Exception as e:
            print(f"[KENTO WARN] spam_loop error chat {chat_id}: {e}")
            await asyncio.sleep(0)

# ═══════════════════════════════════════════════
#              SLIDE REPLY LOOP (reply flood per slide slot)
# ═══════════════════════════════════════════════
async def _resolve_target_user_async(update, context):
    """Resolve a target consistently for slide1-10 and gameover.

    Supported forms: reply, <name>, @username, username, or <user_id>.
    Display names and usernames use the local chat cache first.  Telegram's
    Bot API cannot resolve arbitrary user usernames with get_chat, so the
    direct lookup is only a best-effort fallback for bots/API versions that
    support it.
    """
    msg = getattr(update, "effective_message", None) or getattr(update, "message", None)
    chat_id = update.effective_chat.id if update.effective_chat else None

    # Reply to the target's message.
    if msg and msg.reply_to_message and msg.reply_to_message.from_user:
        user = msg.reply_to_message.from_user
        return user.id, user

    if not context.args or chat_id is None:
        return None, None

    raw = " ".join(context.args).strip()
    if not raw:
        return None, None
    lookup = raw.lstrip("@").casefold()
    cache = known_chat_users.setdefault(chat_id, {})

    # Numeric Telegram user ID.
    try:
        target_id = int(lookup)
        try:
            user = (await context.bot.get_chat_member(chat_id, target_id)).user
        except Exception:
            user = None
        return target_id, user
    except (TypeError, ValueError):
        pass

    # Cached display name / username.  Store and compare all supported forms
    # case-insensitively, with or without the leading @.
    cached = cache.get(lookup)
    if cached:
        return cached

    # Match a cached user's first name, full name, or username.  Iterating
    # over users (rather than cache keys) also handles users cached under a
    # different alias and names containing spaces.
    seen_ids = set()
    for cached_user_id, cached_user in cache.values():
        if cached_user_id in seen_ids or not getattr(cached_user, "id", None):
            continue
        seen_ids.add(cached_user_id)
        first_name = (getattr(cached_user, "first_name", None) or "").casefold()
        last_name = (getattr(cached_user, "last_name", None) or "").casefold()
        full_name = " ".join(x for x in (first_name, last_name) if x).strip()
        username_name = (getattr(cached_user, "username", None) or "").lstrip("@").casefold()
        aliases = {alias for alias in (first_name, full_name, username_name) if alias}
        if lookup and lookup in aliases:
            cache[lookup] = (cached_user.id, cached_user)
            return cached_user.id, cached_user

    # Best-effort direct username lookup. This is supported by some Telegram
    # clients/API wrappers, but group-member cache resolution above is the
    # reliable path for ordinary bot accounts.
    try:
        user = await context.bot.get_chat(f"@{lookup}")
        if getattr(user, "id", None):
            if getattr(user, "first_name", None):
                cache[user.first_name.casefold()] = (user.id, user)
            full_name = " ".join(
                x for x in (
                    getattr(user, "first_name", None),
                    getattr(user, "last_name", None),
                ) if x
            ).casefold()
            if full_name:
                cache[full_name] = (user.id, user)
            if getattr(user, "username", None):
                cache[user.username.lstrip("@").casefold()] = (user.id, user)
            cache[lookup] = (user.id, user)
            return user.id, user
    except Exception:
        pass

    # Fallback for uncached group members/admins.
    try:
        admins = await context.bot.get_chat_administrators(chat_id)
        for admin in admins:
            user = admin.user
            aliases = {
                (user.first_name or "").casefold(),
                " ".join(
                    x for x in ((user.first_name or ""), (user.last_name or ""))
                    if x
                ).casefold(),
                (user.username or "").lstrip("@").casefold(),
            }
            if lookup in aliases:
                if user.first_name:
                    cache[user.first_name.casefold()] = (user.id, user)
                full_name = " ".join(
                    x for x in (user.first_name, user.last_name) if x
                ).casefold()
                if full_name:
                    cache[full_name] = (user.id, user)
                if user.username:
                    cache[user.username.lstrip("@").casefold()] = (user.id, user)
                cache[lookup] = (user.id, user)
                return user.id, user
    except Exception:
        pass

    return None, None


def format_slide_text(template, target_user):
    target_name = (
        getattr(target_user, "first_name", None)
        or getattr(target_user, "username", None)
        or str(target_user.id)
    )
    return template.replace("{target}", target_name)


async def _slide_hold_task(slide_num: int, key: str):
    """Keep slides 1-4 active; message_handler sends their replies."""
    try:
        # This task is only a lifecycle marker.  Waiting on an event avoids
        # the old zero-sleep busy loop while preserving cancellation behavior.
        await asyncio.Event().wait()
    except asyncio.CancelledError:
        raise


async def slide_reply_loop(
    chat_id: int, initial_message_id: int, patterns: list, target_user,
    slide_num: int, target_id: int,
):
    """Continuous reply loop used by slides 5-10."""
    key = f"{chat_id}_{target_id}"
    pattern_list = [p for p in patterns if isinstance(p, str) and p.strip()]
    if not pattern_list:
        return
    current_task = asyncio.current_task()
    index = 0
    try:
        while True:
            if key not in slide_targets_map[slide_num] or slide_reply_tasks[slide_num].get(key) is not current_task:
                break
            text = format_slide_text(pattern_list[index % len(pattern_list)], target_user)
            reply_id = slide_target_message_ids[slide_num].get(key, initial_message_id)

            async def send_one(bot_index: int, bot):
                if not _bot_ready(bot_index):
                    return
                try:
                    kwargs = {"chat_id": chat_id, "text": text}
                    if reply_id:
                        kwargs["reply_to_message_id"] = reply_id
                    await bot.send_message(**kwargs)
                except RetryAfter as exc:
                    _bot_cooldown_set(bot_index, exc.retry_after)
                except asyncio.CancelledError:
                    raise
                except Exception as exc:
                    print(f"[slide{slide_num}] send failed: {exc}")

            await asyncio.gather(*[send_one(i, bot) for i, bot in enumerate(bots)], return_exceptions=True)
            index += 1
            await asyncio.sleep(_current_delay(chat_id))
    except asyncio.CancelledError:
        raise
    finally:
        if slide_reply_tasks[slide_num].get(key) is current_task:
            slide_reply_tasks[slide_num].pop(key, None)
            slide_target_message_ids[slide_num].pop(key, None)
            slide_targets_map[slide_num].discard(key)


# ═══════════════════════════════════════════════
#              PHOTO LOOP
# ═══════════════════════════════════════════════
async def photo_loop(chat_id: int):
    i = 0
    while True:
        try:
            store = photo_store.get(chat_id, [])
            if not store:
                await asyncio.sleep(0.05)
                continue
            _, data = store[i % len(store)]

            async def _set(idx: int, b, d=data):
                if not _bot_ready(idx):
                    return
                try:
                    await b.set_chat_photo(chat_id=chat_id, photo=io.BytesIO(d))
                except RetryAfter as e:
                    _bot_cooldown_set(idx, e.retry_after)
                except asyncio.CancelledError:
                    raise
                except Exception:
                    pass

            await asyncio.gather(*[_set(idx, b) for idx, b in enumerate(bots)])
            i += 1
            await asyncio.sleep(_current_delay(chat_id))
        except asyncio.CancelledError:
            raise
        except Exception as e:
            print(f"[SHIVAM WARN] photo_loop error chat {chat_id}: {e}")
            await asyncio.sleep(0.5)

