@only_owner
async def stopnc(update: Update, context: ContextTypes.DEFAULT_TYPE):
    chat_id = update.message.chat_id
    stopped = False
    for nc_num in range(1, 11):
        if chat_id in nc_tasks[nc_num]:
            for task in nc_tasks[nc_num][chat_id].values():
                task.cancel()
            nc_tasks[nc_num][chat_id] = {}
            stopped = True
    # Also stop named NC commands (from kk.py integration)
    for cmd_name in list(kk_named_nc_tasks.keys()):
        chat_dict = kk_named_nc_tasks[cmd_name]
        if chat_id in chat_dict:
            for bot_key, task in list(chat_dict[chat_id].items()):
                if task and not task.done():
                    task.cancel()
            chat_dict[chat_id] = {}
            stopped = True
    if stopped:
        _boost_state.pop(chat_id, None)
        _last_set_title.pop(chat_id, None)
        await update.message.reply_text("🌙 𝐀ʟʟ 𝐍ᴄ 𝐋ᴏᴏᴘs 𝐒ᴛᴏᴘᴘᴇᴅ🌹")
    else:
        await update.message.reply_text("🤍 𝐍ᴏ 𝐍ᴄ 𝐋ᴏᴏᴘs 𝐀ᴄᴛɪᴠᴇ🌙")

