# ═══════════════════════════════════════════════════════════════════════════════
#              NAMED NC COMMANDS (from kk.py — 52 commands)
#  Each named NC command (nc, tnc, rnc, flagnc, royalnc, ...) renames the
#  chat title using its own text collection from KK_NC_MAP.  These use the
#  same nc_bot_loop infrastructure as nc1–nc10 but store their tasks in a
#  separate kk_named_nc_tasks registry so stopnc / stopall can find them.
# ═══════════════════════════════════════════════════════════════════════════════
def _make_kk_nc_cmd(cmd_name: str, texts: list):
    """Factory: create a named NC command handler from a KK_NC_MAP entry."""
    @only_owner
    async def kk_nc_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
        if not context.args:
            return await update.message.reply_text(f"🥷 𝐄ɴᴛᴇʀ 𝐓ʜᴇ 𝐓ᴀʀɢᴇᴛ » {cmd_name} <ɴᴀᴍᴇ> 🏴")
        base = stylize_name(" ".join(context.args))
        chat_id = update.message.chat_id
        kk_named_nc_tasks.setdefault(cmd_name, {}).setdefault(chat_id, {})
        for bot in bots:
            key = getattr(bot, "token", str(id(bot)))
            if key not in kk_named_nc_tasks[cmd_name][chat_id]:
                task = asyncio.create_task(
                    nc_bot_loop(bot, chat_id, base, texts,
                                len(kk_named_nc_tasks[cmd_name][chat_id]))
                )
                kk_named_nc_tasks[cmd_name][chat_id][key] = task
        await update.message.reply_text(f"🥷 {cmd_name} 𝐒ᴛᴀʀᴛᴇᴅ👑")
    kk_nc_cmd.__name__ = f"{cmd_name}_cmd"
    return kk_nc_cmd

# Instantiate all 52 named NC commands from KK_NC_MAP
_kk_nc_cmds: Dict[str, object] = {}
for _nc_name, _nc_texts in KK_NC_MAP.items():
    # Only register named NCs that actually have message text configured.
    if isinstance(_nc_texts, (list, tuple)) and any(isinstance(t, str) and t.strip() for t in _nc_texts):
        _kk_nc_cmds[_nc_name] = _make_kk_nc_cmd(_nc_name, list(_nc_texts))


