# ═══════════════════════════════════════════════════════════════════════════════
#              NAMED SPAM COLLECTION COMMANDS
#  Named commands select one entry from their configured collection.
#  The collection can be:
#    • None           → plain text spam (uses context.args as the text)
#    • a str key      → looked up in KK_SPAM_COLLECTIONS
#    • a literal list → used directly
#  Tasks are stored in kk_named_spam_tasks so stopall can find them.
# ═══════════════════════════════════════════════════════════════════════════════
def _resolve_kk_spam_collection(value):
    """Resolve a KK_SPAM_MAP value to an actual list of messages."""
    if value is None:
        return None  # plain-text spam (uses args)
    if isinstance(value, list):
        return value
    if isinstance(value, str):
        return KK_SPAM_COLLECTIONS.get(value, [])
    return []


def _make_kk_spam_cmd(cmd_name: str, raw_value):
    """Named collection command: one selected entry per invocation."""
    texts = _resolve_kk_spam_collection(raw_value)
    is_plain = texts is None

    @only_owner
    async def kk_spam_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
        extra = " ".join(context.args) if context.args else ""
        if is_plain:
            if not extra:
                return await update.message.reply_text(f"🥷 𝐒ᴘᴀᴍ » {cmd_name} <text> 🏴")
            text = extra
        else:
            active = [t for t in (texts or []) if isinstance(t, str) and t.strip()]
            if not active:
                return await update.message.reply_text(f"🥷 {cmd_name} 𝐂ᴏʟʟᴇᴄᴛɪᴏɴ 𝐄ᴍᴘᴛʏ 🏴")
            text = random.choice(active)
            if extra:
                text = text.replace("{target}", extra)
        try:
            await update.message.reply_text(text)
        except TelegramError:
            return
    kk_spam_cmd.__name__ = f"{cmd_name}_cmd"
    return kk_spam_cmd


# Instantiate all 19 named spam commands from KK_SPAM_MAP
_kk_spam_cmds: Dict[str, object] = {}
for _spam_name, _spam_val in KK_SPAM_MAP.items():
    _resolved = _resolve_kk_spam_collection(_spam_val)
    # Plain /spam accepts user text; named collections must contain real text.
    if _resolved is None or (isinstance(_resolved, (list, tuple)) and any(isinstance(t, str) and t.strip() for t in _resolved)):
        _kk_spam_cmds[_spam_name] = _make_kk_spam_cmd(_spam_name, _spam_val)


