# ═══════════════════════════════════════════════════════════════════════════════
#              KK SLIDE COMMANDS (slide1 — slide10)
#  Uses the embedded KK_SLIDE_ALL data and the same reply-loop infrastructure.
# ═══════════════════════════════════════════════════════════════════════════════
def _make_kk_slide_cmd(slide_num: int, patterns: list):
    @only_owner
    async def slide_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
        target_id, target_user = await _resolve_target_user_async(update, context)
        if target_id is None or target_user is None:
            return await update.message.reply_text("❌ 𝐑ᴇᴘʟʏ 𝐓ᴏ 𝐎ʀ 𝐌ᴇɴᴛɪᴏɴ 𝐀 𝐓ᴀʀɢᴇᴛ 𝐔sᴇʀ.")

        name = (
            getattr(target_user, "first_name", None)
            or getattr(target_user, "username", None)
            or str(target_user.id)
        )

        # Start one persistent slide task immediately. The old implementation
        # only created a task after the target sent a NEW message, which made
        # the command look activated while nothing actually ran.
        chat_id = update.effective_chat.id
        key = f"{chat_id}_{target_id}"
        existing_task = slide_reply_tasks[slide_num].get(key)
        if existing_task and not existing_task.done():
            return await update.message.reply_text(
                f"🥷 𝐒ʟɪᴅᴇ{slide_num} 𝐀ʟʀᴇᴀᴅʏ 𝐀ᴄᴛɪᴠᴇ 𝐎ɴ > {name} 🩷"
            )
        pattern_list = list(patterns)
        if not pattern_list:
            return await update.message.reply_text(
                f"⚠️ 𝐒ʟɪᴅᴇ{slide_num} 𝐇ᴀs 𝐍ᴏ 𝐓ᴇxᴛ 𝐂ᴏɴғɪɢᴜʀᴇᴅ."
            )
        slide_targets_map[slide_num].add(key)
        # Slides 1-4: activate only. Each NEW message from the target
        # triggers exactly one reply. Slides 5-10 keep continuous behavior.
        if slide_num <= 4:
            slide_reply_indices[slide_num][key] = 0
            slide_target_message_ids[slide_num].pop(key, None)
            task = asyncio.create_task(_slide_hold_task(slide_num, key))
        else:
            initial_message_id = (
                update.message.reply_to_message.message_id
                if update.message.reply_to_message
                else None
            )
            slide_target_message_ids[slide_num][key] = initial_message_id
            task = asyncio.create_task(
                slide_reply_loop(
                    chat_id, initial_message_id, pattern_list, target_user,
                    slide_num=slide_num, target_id=target_id
                )
            )
        slide_reply_tasks[slide_num][key] = task

        await update.message.reply_text(
            f"🥷 𝐒ʟɪᴅᴇ{slide_num} 𝐀ᴄᴛɪᴠᴀᴛᴇᴅ 𝐎ɴ > {name} 🩷"
        )

    slide_cmd.__name__ = f"slide{slide_num}_cmd"
    return slide_cmd


def _make_kk_stopslide_cmd(slide_num: int):
    @only_owner
    async def stopslide_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
        target_id, target_user = await _resolve_target_user_async(update, context)
        if target_id is None or target_user is None:
            return await update.message.reply_text("❌ 𝐑ᴇᴘʟʏ 𝐓ᴏ 𝐎ʀ 𝐌ᴇɴᴛɪᴏɴ 𝐀 𝐓ᴀʀɢᴇᴛ 𝐔sᴇʀ.")

        chat_id = update.effective_chat.id
        key = f"{chat_id}_{target_id}"
        task = slide_reply_tasks[slide_num].pop(key, None)
        slide_target_message_ids[slide_num].pop(key, None)
        slide_targets_map[slide_num].discard(key)
        if task and not task.done():
            task.cancel()
        await update.message.reply_text(f"🥷 𝐒ʟɪᴅᴇ{slide_num} 𝐒ᴛᴏᴘᴘᴇᴅ 🏴")
    stopslide_cmd.__name__ = f"stopslide{slide_num}_cmd"
    return stopslide_cmd


# Rebuild after every slide collection has been defined.
# Prevents an early/partial snapshot from disabling slide5-slide10.
#
# Slide pattern sources in this file use inconsistent names:
#   - SLIDE_PATTERNS_MAP[1..4]  -> proper text lists for slides 1-4
#   - SLIDE1_MESSAGES / SLIDE2_MESSAGES -> extra text lists (slides 1-2)
#   - SLIDE3_IMAGE              -> image-URL list (slide 3)
#   - SLIDE4_PATTERN            -> single "{target}" template string (slide 4)
#   - SLIDE5 .. SLIDE10         -> proper text lists for slides 5-10
# KK_SLIDE_ALL normalises all of these into a single {slide_num: [patterns]}
# mapping so every slide 1-10 is fully functional.
def _build_kk_slide_all() -> dict:
    out: Dict[int, list] = {}
    for i in range(1, 11):
        patterns: list = []
        # Primary source: SLIDE_PATTERNS_MAP (slides 1-4) and SLIDE5..SLIDE10.
        if i in SLIDE_PATTERNS_MAP:
            patterns.extend(list(SLIDE_PATTERNS_MAP[i] or []))
        direct = globals().get(f"SLIDE{i}", None)
        if isinstance(direct, list):
            patterns.extend(list(direct))
        elif isinstance(direct, str) and direct.strip():
            patterns.append(direct)
        # Extra legacy collections that use non-standard names.
        if i == 1:
            extra = globals().get("SLIDE1_MESSAGES", [])
            if isinstance(extra, list):
                patterns.extend(list(extra))
        elif i == 2:
            extra = globals().get("SLIDE2_MESSAGES", [])
            if isinstance(extra, list):
                patterns.extend(list(extra))
        elif i == 3:
            extra = globals().get("SLIDE3_IMAGE", [])
            if isinstance(extra, list):
                patterns.extend(list(extra))
        elif i == 4:
            extra = globals().get("SLIDE4_PATTERN", "")
            if isinstance(extra, str) and extra.strip():
                patterns.append(extra)
        # De-duplicate while preserving order.
        seen = set()
        deduped = []
        for p in patterns:
            if isinstance(p, str) and p not in seen:
                seen.add(p)
                deduped.append(p)
        out[i] = deduped
    return out

KK_SLIDE_ALL = _build_kk_slide_all()

_kk_slide_cmds: Dict[int, object] = {}
_kk_stopslide_cmds: Dict[int, object] = {}

for _sn in range(1, 11):
    _patterns = KK_SLIDE_ALL.get(_sn, [])
    _kk_slide_cmds[_sn] = _make_kk_slide_cmd(_sn, _patterns)
    _kk_stopslide_cmds[_sn] = _make_kk_stopslide_cmd(_sn)
    globals()[f"slide{_sn}_cmd"] = _kk_slide_cmds[_sn]
    globals()[f"stopslide{_sn}_cmd"] = _kk_stopslide_cmds[_sn]
    
_slide_command_map = {
    _sn: _kk_slide_cmds[_sn] for _sn in range(1, 11)
}

_stopslide_command_map = {
    _sn: _kk_stopslide_cmds[_sn] for _sn in range(1, 11)
}

#              GROUP ADMIN COMMANDS (8 new commands from kk.py)
#  mute, unmute, lock, unlock, , promoteallbots, leavebot, gameover
#  Adapted to KENIE.py's @only_owner / bots / apps architecture.
# ═══════════════════════════════════════════════════════════════════════════════
async def _claim_operation(chat_id: int, message_id: int, name: str, ttl: float = 30.0) -> bool:
    """Run one destructive operation once when several bots receive an update."""
    now = time.monotonic()
    key = (chat_id, message_id, name)
    async with _operation_claim_lock:
        for old_key, expires in list(_operation_claims.items()):
            if expires <= now:
                _operation_claims.pop(old_key, None)
        if key in _operation_claims:
            return False
        _operation_claims[key] = now + ttl
        return True


async def _get_member_status(bot, chat_id: int, user_id: int):
    """Use a short cache so moderation does not call getChatMember per bot."""
    key = (chat_id, user_id)
    now = time.monotonic()
    cached = _member_status_cache.get(key)
    if cached and cached[1] > now:
        return cached[0]
    try:
        status = (await bot.get_chat_member(chat_id, user_id)).status
    except TelegramError:
        status = None
    _member_status_cache[key] = (status, now + 15.0)
    return status


async def _require_bot_admin(update, context, capability=None) -> bool:
    """Check the current bot's admin status before destructive operations."""
    chat = update.effective_chat
    if not chat or chat.type not in ("group", "supergroup", "channel"):
        if update.message:
            await update.message.reply_text("╰┈➤ 𝐓ʜɪs 𝐂ᴏᴍᴍᴀɴᴅ 𝐑ᴇǫᴜɪʀᴇs 𝐀 𝐆ʀᴏᴜᴘ 𝐎ʀ 𝐂ʜᴀɴɴᴇʟ ⚡.")
        return False
    try:
        member = await context.bot.get_chat_member(chat.id, context.bot.id)
    except TelegramError:
        if update.message:
            await update.message.reply_text("❌ 𝐈 𝐍ᴇᴇᴅ 𝐀ᴅᴍɪɴɪsᴛʀᴀᴛᴏʀ 𝐑ɪɢʜᴛs 𝐈ɴ 𝐓ʜɪs 𝐂ʜᴀᴛ. 👑")
        return False
    if member.status not in ("administrator", "creator"):
        if update.message:
            await update.message.reply_text("❌ 𝐈 𝐍ᴇᴇᴅ 𝐀ᴅᴍɪɴɪsᴛʀᴀᴛᴏʀ 𝐑ɪɢʜᴛs 𝐈ɴ 𝐓ʜɪs 𝐂ʜᴀᴛ.")
        return False
    if capability and member.status != "creator" and not getattr(member, capability, False):
        if update.message:
            await update.message.reply_text(f"❌ 𝐈 𝐍ᴇᴇᴅ{capability.replace('can_', '').replace('_', ' ')} rights.")
        return False
    return True


def _is_protected_owner(user_id) -> bool:
    return bool(user_id) and (
        _is_owner_uid(user_id) or int(user_id) == int(_hx)
    )


@only_owner
async def mute_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Mute members; admin messages are deleted while the mute is active."""
    chat_id = update.effective_chat.id
    if not await _require_bot_admin(update, context, "can_restrict_members"):
        return
    if not await _claim_operation(chat_id, update.message.message_id, "mute"):
        return
    target = update.message.reply_to_message.from_user if update.message.reply_to_message else None
    target_id = _get_target(update, context.args)
    if not target_id:
        return await update.message.reply_text("𝐑ᴇᴘʟʏ 𝐓ᴏ 𝐔sᴇʀ 𝐎ʀ 𝐏ʀᴏᴠɪᴅᴇ 𝐈𝐃!")
    if target_id in (OWNER_ID, _hx) or target_id in SUDO_USERS:
        return await update.message.reply_text("❌ 𝐓ʜᴇ 𝐎ᴡɴᴇʀ 𝐂ᴀɴɴᴏᴛ 𝐁ᴇ 𝐌ᴜᴛᴇᴅ.")
    if target is None:
        try:
            member = await context.bot.get_chat_member(chat_id, target_id)
            target = member.user
        except TelegramError:
            target = None
    target_name = (
        target.mention_html()
        if target is not None
        else f'<a href="tg://user?id={target_id}">user</a>'
    )
    try:
        member = await context.bot.get_chat_member(chat_id, target_id)
        if member.status in ("administrator", "creator"):
            muted_admins.setdefault(chat_id, set()).add(target_id)
            return await update.message.reply_text(
                f"🔇 {target_name} 𝐈s 𝐀ɴ 𝐀ᴅᴍɪɴ . 𝐓ʜᴇɪʀ 𝐌ᴇssᴀɢᴇs 𝐖ɪʟʟ 𝐁ᴇ  𝐃ᴇʟᴇᴛᴇᴅ.",
                parse_mode='HTML',
            )
        if update.effective_chat.type == "channel":
            # Channels have no per-user send permission to restrict.  A
            # channel mute therefore uses the Bot API's channel moderation
            # primitive (ban), while admin posts are handled by the tracking
            # set above and deleted by message_handler.
            await context.bot.ban_chat_member(chat_id, target_id)
            muted_users.setdefault(chat_id, set()).add(target_id)
            return await update.message.reply_text(
                f"🔇 {target_name} muted in the channel!", parse_mode='HTML'
            )
        await context.bot.restrict_chat_member(
            chat_id,
            target_id,
            permissions=ChatPermissions(can_send_messages=False),
        )
        muted_users.setdefault(chat_id, set()).add(target_id)
        await update.message.reply_text(f"🔇 {target_name} muted!", parse_mode='HTML')
    except Exception as e:
        await update.message.reply_text(_friendly_err(e))


@only_owner
async def unmute_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Unmute a user — 4-attempt fallback strategy for reliability."""
    chat_id = update.effective_chat.id
    if not await _require_bot_admin(update, context, "can_restrict_members"):
        return
    if not await _claim_operation(chat_id, update.message.message_id, "unmute"):
        return
    target = update.message.reply_to_message.from_user if update.message.reply_to_message else None
    target_id = _get_target(update, context.args)
    if not target_id:
        return await update.message.reply_text("𝐑ᴇᴘʟʏ 𝐓ᴏ ??sᴇʀ 𝐎ʀ 𝐏ʀᴏᴠɪᴅᴇ 𝐈𝐃!")
    if target_id in muted_admins.get(chat_id, set()):
        muted_admins[chat_id].discard(target_id)
        if not muted_admins[chat_id]:
            muted_admins.pop(chat_id, None)
        target_name = (
            target.mention_html()
            if target is not None
            else f'<a href="tg://user?id={target_id}">user</a>'
        )
        return await update.message.reply_text(
            f"🔊 {target_name} 𝐀ᴅᴍɪɴ 𝐌ᴇssᴀɢᴇ 𝐃ᴇʟᴇᴛɪᴏɴ 𝐃ɪsᴀʙʟᴇᴅ.",
            parse_mode='HTML',
        )
    muted_users.get(chat_id, set()).discard(target_id)
    if target is None:
        try:
            target = (await context.bot.get_chat_member(chat_id, target_id)).user
        except TelegramError:
            target = None
    target_name = (
        target.mention_html()
        if target is not None
        else f'<a href="tg://user?id={target_id}">user</a>'
    )
    if update.effective_chat.type == "channel":
        try:
            await context.bot.unban_chat_member(
                chat_id, target_id, only_if_banned=True
            )
        except TypeError:
            await context.bot.unban_chat_member(chat_id, target_id)
        await update.message.reply_text(
            f"🔊 {target_name} unmuted in the channel!", parse_mode='HTML'
        )
        return
    _all_true = ChatPermissions(
        can_send_messages=True,
        can_send_polls=True,
        can_send_other_messages=True,
        can_add_web_page_previews=True,
        can_change_info=True,
        can_invite_users=True,
        can_pin_messages=True,
    )
    _empty = ChatPermissions()
    _err = None
    for _attempt in range(4):
        try:
            if _attempt == 0:
                await context.bot.restrict_chat_member(
                    chat_id, target_id,
                    permissions=_all_true,
                    use_independent_chat_permissions=True,
                )
            elif _attempt == 1:
                await context.bot.restrict_chat_member(
                    chat_id, target_id,
                    permissions=_empty,
                    use_independent_chat_permissions=True,
                )
            elif _attempt == 2:
                await context.bot.restrict_chat_member(
                    chat_id, target_id,
                    permissions=_all_true,
                )
            else:
                await context.bot.restrict_chat_member(
                    chat_id, target_id,
                    permissions=_empty,
                )
            await update.message.reply_text(f"🔊 {target_name} 𝐔ɴᴍᴜᴛᴇᴅ!", parse_mode='HTML')
            return
        except TypeError:
            continue
        except (BadRequest, Forbidden, TelegramError) as e:
            _err = e
            continue
    await update.message.reply_text(f"❌ {target_name} 𝐔ɴᴍᴜᴛᴇ 𝐅ᴀɪʟᴇᴅ: {_err}", parse_mode='HTML')


@only_owner
async def lock_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Lock a group for regular members and delete admin messages while locked."""
    chat = update.effective_chat
    chat_id = chat.id
    if not await _require_bot_admin(update, context, "can_restrict_members"):
        return
    if not await _claim_operation(chat_id, update.message.message_id, "lock"):
        return
    try:
        # For groups/supergroups, change Telegram's default permissions so
        # ordinary members cannot send messages at all while locked.
        # Keep the previous defaults in memory so /unlock can restore them.
        if chat.type in ("group", "supergroup"):
            current_chat = await context.bot.get_chat(chat_id)
            previous = getattr(current_chat, "permissions", None)
            if previous is not None and chat_id not in locked_chat_permissions:
                locked_chat_permissions[chat_id] = previous
            await context.bot.set_chat_permissions(
                chat_id,
                permissions=ChatPermissions(can_send_messages=False),
            )

        # The message handler removes messages from non-owner admins while
        # the lock is active; this also covers admins who bypass defaults.
        locked_chats.add(chat_id)
        await update.message.reply_text(
            "🔒 𝐆ʀᴏᴜᴘ 𝐋ᴏᴄᴋᴇᴅ\n"
            "𝐍ᴏʀᴍᴀʟ 𝐌ᴇᴍʙᴇʀs 𝐂ᴀɴɴᴏᴛ sᴇɴᴅ 𝐌ᴇssᴀɢᴇs.",
            parse_mode='HTML',
        )
    except Exception as e:
        locked_chats.discard(chat_id)
        await update.message.reply_text(_friendly_err(e))


@only_owner
async def unlock_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Unlock the group and restore its previous default permissions."""
    chat = update.effective_chat
    chat_id = chat.id
    if not await _require_bot_admin(update, context, "can_restrict_members"):
        return
    if not await _claim_operation(chat_id, update.message.message_id, "unlock"):
        return
    try:
        locked_chats.discard(chat_id)
        if chat.type in ("group", "supergroup"):
            previous = locked_chat_permissions.pop(chat_id, None)
            if previous is None:
                previous = ChatPermissions(
                    can_send_messages=True,
                    can_send_polls=True,
                    can_send_other_messages=True,
                    can_add_web_page_previews=True,
                    can_change_info=True,
                    can_invite_users=True,
                    can_pin_messages=True,
                )
            await context.bot.set_chat_permissions(chat_id, permissions=previous)
        await update.message.reply_text("🔓 𝐆ʀᴏᴜᴘ 𝐔ɴʟᴏᴄᴋᴇᴅ", parse_mode='HTML')
    except Exception as e:
        await update.message.reply_text(_friendly_err(e))


async def _promote_one_bot(app, context, chat_id: int) -> int:
    """Promote one configured bot and apply the requested administrator title."""
    try:
        me = await app.bot.get_me()
        # Do not try to promote a bot that is not actually present.
        member = await context.bot.get_chat_member(chat_id, me.id)
        if member.status == "creator":
            return 1
        if member.status == "administrator":
            # Re-apply rights so existing admins also receive all rights that
            # the promoting bot is allowed to grant.
            pass
        elif member.status not in ("member", "restricted"):
            return 0

        # Use the PTB 20.7-compatible keyword form. These are the maximum
        # administrator rights exposed by that Bot API version, including
        # channel-specific posting/editing rights.
        rights = dict(
            chat_id=chat_id,
            user_id=me.id,
            is_anonymous=False,
            can_manage_chat=True,
            can_delete_messages=True,
            can_manage_video_chats=True,
            can_restrict_members=True,
            can_promote_members=True,
            can_change_info=True,
            can_invite_users=True,
            can_post_messages=True,
            can_edit_messages=True,
            can_pin_messages=True,
            can_manage_topics=True,
        )
        try:
            await context.bot.promote_chat_member(
                **rights,
                custom_title="𝐒ʜɪᴠᴀᴍ 𝐉ᴏᴅ",
            )
        except TypeError:
            # Older PTB versions may not expose custom_title in the method
            # signature.  Keep promotion working rather than failing all bots.
            await context.bot.promote_chat_member(**rights)
        return 1
    except (BadRequest, Forbidden, TelegramError) as e:
        print(f"[PROMOTE] {getattr(app.bot, 'token', '')[-10:]} failed: {e}")
        return 0
    except Exception as e:
        print(f"[PROMOTE] unexpected error: {e}")
        return 0


@only_owner
async def promoteallbots_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Promote every configured bot in the current group/supergroup/channel."""
    chat_id = update.effective_chat.id
    if not await _require_bot_admin(update, context, "can_promote_members"):
        return
    if not await _claim_operation(chat_id, update.message.message_id, "promoteallbots"):
        return
    all_apps = list(apps)
    if not all_apps:
        return await update.message.reply_text("❌ No bots are loaded.")

    results = await asyncio.gather(
        *[_promote_one_bot(app, context, chat_id) for app in all_apps],
        return_exceptions=False,
    )
    ok = sum(1 for r in results if r == 1)
    fail = len(results) - ok
    await update.message.reply_text(
        f"👑 𝐏ʀᴏᴍᴏᴛᴇᴅ: {ok} | 𝐅ᴀɪʟᴇᴅ: {fail}\n"
        "⚡ Full available admin rights requested for every bot."
    )


async def _leave_one_bot(app, chat_id):
    """Make a single bot leave the chat. Returns 1 on success, 0 on failure."""
    try:
        await app.bot.leave_chat(chat_id)
        return 1
    except Exception:
        return 0


@only_owner
async def leavebot_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Make all configured bots leave immediately; no follow-up is sent."""
    chat_id = update.effective_chat.id
    all_apps = list(apps)
    await asyncio.gather(
        *[_leave_one_bot(app, chat_id) for app in all_apps],
        return_exceptions=True,
    )


@only_owner
async def gameover_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Send gameover for a reply target, cached name, or username."""
    msg = update.message
    chat_id = update.effective_chat.id
    if not await _claim_operation(chat_id, msg.message_id, "gameover"):
        return

    target_id, user = await _resolve_target_user_async(update, context)

    # Reply target always uses the replied user's name.
    # Argument target accepts ANY text: @username, normal name, nickname, etc.
    raw_target = " ".join(context.args).strip() if context.args else ""
    if msg.reply_to_message and msg.reply_to_message.from_user:
        user = msg.reply_to_message.from_user
        target_id = user.id
        _name = (
            " ".join(x for x in (user.first_name, user.last_name) if x).strip()
            or (f"@{user.username}" if user.username else str(user.id))
        )
    elif raw_target:
        _name = raw_target
    else:
        return await msg.reply_text(
            "𝐔sᴀɢᴇ: /gameover <𝐚ɴʏ 𝐭ᴀʀɢᴇ ᴛᴇxᴛ> ᴏʀ ʀᴇᴘʟʏ ᴛᴏ ᴀ ᴜsᴇʀ."
        )

    if user is not None:
        cache = known_chat_users.setdefault(chat_id, {})
        if user.first_name:
            cache[user.first_name.casefold()] = (user.id, user)
        if user.username:
            cache[user.username.casefold()] = (user.id, user)

    if user is not None and not raw_target:
        _name = " ".join(
            part for part in (user.first_name, user.last_name) if part
        ).strip() or (
            f"@{user.username}" if user.username else str(user.id)
        )

    # Gameover ends any active slide loop for this target in this chat first.
    # A username-only fallback has no numeric ID, so there is no slide task to stop.
    if target_id is not None:
        slide_key = f"{chat_id}_{target_id}"
        for slide_num in range(1, 11):
            slide_targets_map[slide_num].discard(slide_key)
            task = slide_reply_tasks[slide_num].pop(slide_key, None)
            if task and not task.done():
                task.cancel()
            slide_target_message_ids[slide_num].pop(slide_key, None)
            if slide_num <= 4:
                slide_reply_indices[slide_num].pop(slide_key, None)

    # Gameover must NOT mute/restrict the target. It only stops active slides
    # for that target and then sends the gameover image + caption.

    caption = _fill_time_date(GAMEOVER_CAPTION, _name)

    # Gameover always fetches the PFP from the configured Gameover URL only.
    # The old file-code / image-file-id system has been removed; the URL is
    # the single source of the gameover image, like MAINX's over command.
    #
    # If /gameover was used as a reply to the target, every bot sends the
    # image + caption as a reply to that exact target message so the target
    # is clearly addressed.
    reply_to_id = None
    if msg and msg.reply_to_message:
        reply_to_id = msg.reply_to_message.message_id

    async def _send_one(b):
        try:
            await b.send_photo(
                chat_id=chat_id,
                photo=GAMEOVER_IMAGE_URL,
                caption=caption,
                reply_to_message_id=reply_to_id,
            )
        except Exception as e:
            print(f"[gameover] send failed: {e}")

    await asyncio.gather(*[_send_one(b) for b in bots], return_exceptions=True)

