#              PURGE COMMANDS
# ═══════════════════════════════════════════════
@only_owner
async def purge_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Delete N contiguous messages, starting at a reply when supplied."""
    msg = update.message
    if not msg:
        return
    if not await _require_bot_admin(update, context, "can_delete_messages"):
        return
    if not await _claim_operation(msg.chat_id, msg.message_id, "purge"):
        return
    try:
        count = int(context.args[0]) if context.args else 0
    except (TypeError, ValueError):
        return await msg.reply_text("𝐔sᴀɢᴇ: /purge <count>")
    count = max(1, min(count, 100))
    if msg.reply_to_message:
        start_id = msg.reply_to_message.message_id
        ids = list(range(start_id, start_id + count))
    else:
        # The command itself is the newest known message, so include it and
        # walk backward.  This also deletes messages from admins/owners.
        ids = list(range(max(1, msg.message_id - count + 1), msg.message_id + 1))

    semaphore = asyncio.Semaphore(8)

    async def delete_one(message_id: int) -> bool:
        async with semaphore:
            try:
                await context.bot.delete_message(
                    chat_id=msg.chat_id,
                    message_id=message_id,
                )
                return True
            except (BadRequest, Forbidden, TelegramError):
                return False
            except Exception:
                return False

    results = await asyncio.gather(*(delete_one(mid) for mid in ids))
    deleted = sum(results)
    # The command message may have been deleted as part of the range.
    if deleted == 0:
        try:
            await msg.reply_text("⚠️ 𝐍ᴏᴛʜɪɴɢ 𝐖ᴀs 𝐃ᴇʟᴇᴛᴇᴅ. 𝐌ᴀᴋᴇ 𝐒ᴜʀᴇ 𝐓ʜᴇ 𝐁ᴏᴛ 𝐂ᴀɴ 𝐃ᴇʟᴇᴛᴇ 𝐌ᴇssᴀɢᴇs.")
        except Exception:
            pass


@only_owner
async def purgeme_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Delete the requested number of the owner's tracked messages."""
    msg = update.message
    if not msg:
        return
    if not await _require_bot_admin(update, context, "can_delete_messages"):
        return
    if not await _claim_operation(msg.chat_id, msg.message_id, "purgeme"):
        return
    chat_id = msg.chat_id
    try:
        count = int(context.args[0]) if context.args else 0
    except (TypeError, ValueError):
        return await msg.reply_text("𝐔sᴀɢᴇ: /purgeme <count>")
    count = max(1, min(count, 1000))
    ids = list(dict.fromkeys(owner_message_ids.get(chat_id, [])))
    # Include the current /purgeme command itself when it was not observed by
    # the message cache (for example, a channel post update).
    if msg.message_id not in ids:
        ids.append(msg.message_id)
    ids = ids[-count:]
    deleted = 0
    remaining = []
    for mid in reversed(ids):
        try:
            await context.bot.delete_message(chat_id=chat_id, message_id=mid)
            deleted += 1
        except (BadRequest, Forbidden, TelegramError):
            continue
        except Exception:
            remaining.append(mid)
    owner_message_ids[chat_id] = list(reversed(remaining))[-500:]

