@only_owner
async def status_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    msg = "🌹 𝐒ʜɪ𝐕ᴀᴍ 𝐀ᴄᴛɪᴠᴇ 𝐋ᴏᴏᴘs👑\n\n"
    has_any = False
    for nc_num in range(1, 11):
        for chat_id, tasks in nc_tasks[nc_num].items():
            if tasks:
                boost = _boost_state.get(chat_id, 0)
                mode = f"⚡ 𝐓ᴜʀʙᴏ ({boost} 𝐋ᴇғᴛ)" if boost > 0 else "🌙 𝐍ᴏʀᴍᴀʟ"
                msg += f"🌹 𝐍ᴄ{nc_num} · 𝐂ʜᴀᴛ {chat_id} · {len(tasks)} 𝐁ᴏᴛs | {mode}\n"
                has_any = True
    for spam_num in range(1, 5):
        active = len(spam_tasks[spam_num])
        if active:
            msg += f"🏹 𝐒ᴘᴀᴍ{spam_num} 𝐀ᴄᴛɪᴠᴇ 𝐈ɴ{active}   𝐂ʜᴀᴛ(s)\n"
            has_any = True
    # Named NC commands (kk.py style)
    for cmd_name, chat_dict in kk_named_nc_tasks.items():
        for chat_id, tasks in chat_dict.items():
            if tasks:
                msg += f"🥷 {cmd_name} · chat {chat_id} · {len(tasks)} bots\n"
                has_any = True
    # Named spam commands (kk.py style)
    for cmd_name, chat_dict in kk_named_spam_tasks.items():
        if chat_dict:
            msg += f"🥷 {cmd_name} spam active in {len(chat_dict)} chat(s)\n"
            has_any = True
    if photo_loop_tasks:
        msg += f"🌹 𝐏ʜᴏᴛᴏ 𝐋ᴏᴏᴘ 𝐀ᴄᴛɪᴠᴇ 𝐈ɴ {len(photo_loop_tasks)} 𝐂ʜᴀᴛ(𝓼)\n"
        has_any = True
    if not has_any:
        msg += "🤍 𝐍ᴏ 𝐀ᴄᴛɪᴠᴇ 𝐋ᴏᴏᴘs🌙"
    await update.message.reply_text(msg)


@only_owner
async def stopall(update: Update, context: ContextTypes.DEFAULT_TYPE):
    chat_id = update.message.chat_id

    to_cancel: list = []

    for nc_num in range(1, 11):
        if chat_id in nc_tasks[nc_num]:
            to_cancel.extend(nc_tasks[nc_num][chat_id].values())
            del nc_tasks[nc_num][chat_id]

    # Named NC commands (kk.py style: nc, tnc, rnc, flagnc, ...)
    for cmd_name in list(kk_named_nc_tasks.keys()):
        if chat_id in kk_named_nc_tasks[cmd_name]:
            to_cancel.extend(kk_named_nc_tasks[cmd_name][chat_id].values())
            del kk_named_nc_tasks[cmd_name][chat_id]

    for spam_num in range(1, 5):
        if chat_id in spam_tasks[spam_num]:
            to_cancel.append(spam_tasks[spam_num][chat_id])
            del spam_tasks[spam_num][chat_id]

    # Named spam commands (kk.py style: emospam, heartspam, ...)
    for cmd_name in list(kk_named_spam_tasks.keys()):
        if chat_id in kk_named_spam_tasks[cmd_name]:
            to_cancel.append(kk_named_spam_tasks[cmd_name][chat_id])
            del kk_named_spam_tasks[cmd_name][chat_id]

    for slide_num in range(1, 11):
        keys_to_del = [k for k in slide_reply_tasks[slide_num] if k.startswith(f"{chat_id}_")]
        for k in keys_to_del:
            slide_target_message_ids[slide_num].pop(k, None)
            if slide_num <= 4:
                slide_reply_indices[slide_num].pop(k, None)
        for k in keys_to_del:
            to_cancel.append(slide_reply_tasks[slide_num][k])
            del slide_reply_tasks[slide_num][k]

    if chat_id in photo_loop_tasks:
        to_cancel.append(photo_loop_tasks[chat_id])
        del photo_loop_tasks[chat_id]

    _boost_state.pop(chat_id, None)
    _last_set_title.pop(chat_id, None)
    muted_admins.pop(chat_id, None)
    muted_users.pop(chat_id, None)
    for key in [key for key in _member_status_cache if key[0] == chat_id]:
        _member_status_cache.pop(key, None)

    for t in to_cancel:
        t.cancel()
    if to_cancel:
        await asyncio.gather(*to_cancel, return_exceptions=True)

    await update.message.reply_text("🌙 𝐀ʟʟ 𝐋ᴏᴏᴘs 𝐒ᴛᴏᴘᴘᴇᴅ 𝐈ɴ 𝐓ʜɪs 𝐂ʜᴀᴛ 🌹")

# ═══════════════════════════════════════════════
#              AUTO REMOVE (foreign bots)
# ═══════════════════════════════════════════════
async def autoremove_handler(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not update.chat_member:
        return
    chat_id = update.chat_member.chat.id
    if chat_id not in autoremove_chats:
        return

    new_member = update.chat_member.new_chat_member
    old_member = update.chat_member.old_chat_member

    joined_statuses = ("member", "administrator", "creator", "restricted")

    if new_member.status not in joined_statuses:
        return
    if old_member.status in joined_statuses:
        return

    user = new_member.user
    if not user.is_bot:
        return
    if user.id in our_bot_ids:
        return

    for bot in bots:
        try:
            await bot.ban_chat_member(chat_id=chat_id, user_id=user.id)
            await asyncio.sleep(0)
            await bot.unban_chat_member(chat_id=chat_id, user_id=user.id)
            print(f"[SHIVAM AUTOREMOVE] Kicked foreign bot {user.id} ({user.username}) from {chat_id}")
            break
        except Exception as e:
            print(f"[SHIVAM AUTOREMOVE] Failed to kick bot {user.id}: {e}")
            continue


