# ── Timezone, caption template & helper functions for group commands ──
_IST = timezone(timedelta(hours=5, minutes=30))

GAMEOVER_IMAGE_URL = "https://files.catbox.moe/g2nklw.jpg"

GAMEOVER_CAPTION = """
╔═══════════════════════╗
                  🪼🌸  {target}
          ⚡ 𝐆ᴀᴍᴇ 𝐎ᴠᴇʀ • 𝐑ᴇsᴜʟᴛ ⚡

		✦ 𝐒ʜɪ𝐕ᴀᴍ 𝐁ᴀᴀᴘ 𝐒ᴇ 𝐒ᴀʜɪ 𝐂ʜᴜᴅ𝐀 😂👞

              ⏰ 𝐆ᴀᴍᴇ 𝐎ᴠᴇʀ 𝐀ᴛ : {time}
                    📅 𝐃ᴀᴛᴇ : {date}

                🏆 𝐓ᴀʀɢᴇᴛ : {target}
            ✅ 𝐒ᴛᴀᴛᴜs : 𝐂ʜᴜᴅᴀɪ 𝐃ᴏɴᴇ

              🪼 𝐁ʏ 𝐒ʜɪ𝐕ᴀᴍ

╚═══════════════════════╝"""


def _fill_time_date(text: str, target: str = "") -> str:
    """Replace placeholders with live values and always return a string."""
    if isinstance(text, (list, tuple)):
        text = "".join(str(x) for x in text)
    if text is None:
        return ""
    text = str(text)
    text = text.replace("{target}", target or "")
    now = datetime.now(_IST)
    # 12-hour AM/PM format for the Gameover caption.
    text = text.replace("{time}", now.strftime("%I:%M:%S %p"))
    text = text.replace("{date}", now.strftime("%d/%m/%Y"))
    return text


def _resolve_target_user(update, args):
    """Backward-compatible synchronous resolver for existing handlers."""
    msg = update.message
    chat_id = update.effective_chat.id if update.effective_chat else None
    if msg and msg.reply_to_message and msg.reply_to_message.from_user:
        user = msg.reply_to_message.from_user
        return user.id, user
    if not args or chat_id is None:
        return None, None
    lookup = " ".join(args).strip().lstrip("@").casefold()
    try:
        return int(lookup), None
    except ValueError:
        return known_chat_users.get(chat_id, {}).get(lookup, (None, None))


def _get_target(update, args):
    """Backward-compatible target ID helper."""
    target_id, _ = _resolve_target_user(update, args)
    return target_id


def _friendly_err(e) -> str:
    """Convert Telegram API errors to short, user-friendly messages."""
    msg = str(e).lower()
    if "chat_admin_required" in msg or "need to be an admin" in msg:
        return "❌ I need admin rights in this chat to do that!\n👉 Promote me as admin with ban/mute permissions."
    if "user_not_participant" in msg:
        return "❌ That user is not in this chat."
    if "can't restrict chat creator" in msg or "can't restrict self" in msg:
        return "❌ Can't restrict the chat creator or yourself."
    if "not enough rights to restrict" in msg:
        return "❌ I don't have enough rights to restrict this user.\n👉 Give me ban/mute permissions."
    if "peer_id_invalid" in msg:
        return "❌ Invalid chat or user ID."
    if "user_id_invalid" in msg:
        return "❌ Invalid user ID."
    if "chat_not_found" in msg:
        return "❌ Chat not found."
    if "message_to_delete_not_found" in msg:
        return "❌ Message not found or already deleted."
    if "message_cant_be_deleted" in msg:
        return "❌ This message can't be deleted (too old or from another admin)."
    if "reply_message_not_found" in msg:
        return "❌ You need to reply to a message to use this command."
    if "bad_request" in msg:
        return f"❌ Bad request: {e}"
    if "forbidden" in msg:
        return "❌ Forbidden: bot was kicked or lacks permissions."
    return f"❌ {e}"


