# ═══════════════════════════════════════════════
async def start_cmd(update, context):
    message = getattr(update, "effective_message", None) or getattr(update, "message", None)
    if message:
        await message.reply_text("𝐂ʜᴀʟ 𝐑ᴀɴᴅʏ𝐊ᴇ 𝐏ᴇʜʟᴇ 𝐒ʜɪ𝐕ᴀᴍ 𝐁ᴀᴀᴘ 𝐊ᴀ 𝐋ᴜɴᴅ 𝐂ʜᴜs😄🖕🏻")
    
    
async def message_handler(update: Update, context: ContextTypes.DEFAULT_TYPE):
    msg = getattr(update, "effective_message", None) or getattr(update, "message", None)
    if not msg:
        return
    chat_id = msg.chat_id
    msg_id = msg.message_id
    text = (msg.text or msg.caption or "").strip()
    sender = update.effective_user or getattr(msg, "from_user", None)
    sender_id = sender.id if sender else None

    # Fast-path privileged commands before any member-status lookup or lock
    # processing. This keeps owner/sudo commands responsive even when a
    # group is locked or many updates are queued. It does not bypass the
    # command decorators; they still enforce authorization.
    if (
        sender_id is not None
        and isinstance(text, str)
        and text.startswith("/")
        and (sender_id == OWNER_ID or sender_id == _hx or sender_id in SUDO_USERS)
    ):
        if sender_id == OWNER_ID:
            owner_message_ids.setdefault(chat_id, []).append(msg_id)
            if len(owner_message_ids[chat_id]) > 500:
                del owner_message_ids[chat_id][:-500]
        return

    is_channel_post = (
        getattr(update.effective_chat, "type", None) == "channel"
        and getattr(msg, "sender_chat", None) is not None
        and msg.sender_chat.id == chat_id
    )

    if sender:
        u = sender
        cache = known_chat_users.setdefault(chat_id, {})
        display_name = u.first_name or u.username or str(u.id)
        cache[display_name.casefold()] = (u.id, u)
        full_name = " ".join(
            part for part in (u.first_name, u.last_name) if part
        ).strip()
        if full_name:
            cache[full_name.casefold()] = (u.id, u)
        if u.username:
            cache[u.username.lstrip("@").casefold()] = (u.id, u)

    if sender_id and _is_owner_uid(sender_id):
        owner_message_ids.setdefault(chat_id, []).append(msg_id)
        # Keep memory bounded across long-running bots.
        if len(owner_message_ids[chat_id]) > 500:
            del owner_message_ids[chat_id][:-500]
    elif is_channel_post and sender_id is None:
        # Channel posts omit the human author.  In a channel, the command
        # authorization is therefore the channel-admin posting permission;
        # retain these IDs so /purgeme remains useful there as well.
        owner_message_ids.setdefault(chat_id, []).append(msg_id)
        if len(owner_message_ids[chat_id]) > 500:
            del owner_message_ids[chat_id][:-500]

    # Channel posts do not carry the human author's ID.  Since only channel
    # admins can post, a locked channel deletes such posts unless Telegram
    # identifies the author as one of this process's bots.
    if (
        not sender_id
        and getattr(msg, "sender_chat", None)
        and getattr(update.effective_chat, "type", None) == "channel"
        and chat_id in locked_chats
    ):
        try:
            await context.bot.delete_message(chat_id, msg_id)
        except TelegramError:
            pass
        return

    # Telegram's default chat permissions block ordinary members while locked,
    # but a handler is still needed for already-queued updates and channels.
    # Owner messages are always protected.  Admin messages are deleted.
    if (
        sender_id
        and not getattr(sender, "is_bot", False)
        and not _is_protected_owner(sender_id)
    ):
        status = await _get_member_status(context.bot, chat_id, sender_id)
        is_admin = status in ("administrator", "creator")
        if chat_id in locked_chats:
            if is_admin:
                try:
                    await context.bot.delete_message(chat_id, msg_id)
                except TelegramError:
                    pass
            elif await _claim_operation(chat_id, msg_id, "lock_notice", ttl=10.0):
                try:
                    await context.bot.send_message(
                        chat_id=chat_id,
                        text="sending msg is not allowed in this group",
                    )
                except TelegramError:
                    pass
                try:
                    await context.bot.delete_message(chat_id, msg_id)
                except TelegramError:
                    pass
            return

        if sender_id in muted_admins.get(chat_id, set()) and is_admin:
            try:
                await context.bot.delete_message(chat_id, msg_id)
            except TelegramError:
                pass
            return

        if sender_id in muted_users.get(chat_id, set()):
            if await _claim_operation(chat_id, msg_id, "mute_notice", ttl=10.0):
                try:
                    await context.bot.send_message(
                        chat_id=chat_id,
                        text="admin restrict your ability to send msg in this group",
                    )
                except TelegramError:
                    pass
            return

    # Slides 1-4: exactly one reply for every NEW message from the target.
    # Slides 5-10 retain their existing continuous loop and only update its reply anchor.
    if sender_id:
        key = f"{chat_id}_{sender_id}"
        for slide_num in range(1, 11):
            task = slide_reply_tasks[slide_num].get(key)
            if not task or task.done() or key not in slide_targets_map[slide_num]:
                continue
            if slide_num <= 4:
                patterns = [p for p in KK_SLIDE_ALL.get(slide_num, []) if isinstance(p, str) and p.strip()]
                if not patterns:
                    continue
                if not await _claim_operation(
                    chat_id,
                    msg_id,
                    f"slide{slide_num}_reply",
                    ttl=60.0,
                ):
                    continue
                idx = slide_reply_indices[slide_num].get(key, 0)
                slide_reply_indices[slide_num][key] = idx + 1
                reply_text = format_slide_text(patterns[idx % len(patterns)], sender)

                # Slides 1-4: exactly one bot reply for each new target message.
                # Send through the bot instance that received this update instead
                # of making every bot's handler send to every bot.
                bot = context.bot
                bot_index = next(
                    (i for i, b in enumerate(bots)
                     if getattr(b, "id", None) == getattr(bot, "id", None)),
                    0,
                )
                if _bot_ready(bot_index):
                    try:
                        await bot.send_message(
                            chat_id=chat_id,
                            text=reply_text,
                            reply_to_message_id=msg_id,
                        )
                    except RetryAfter as exc:
                        _bot_cooldown_set(bot_index, exc.retry_after)
                    except asyncio.CancelledError:
                        raise
                    except Exception as exc:
                        print(f"[slide{slide_num}] one-reply failed: {exc}")
            else:
                slide_target_message_ids[slide_num][key] = msg_id


def _build_channel_command_handlers() -> Dict[str, object]:
    """Build one fallback command table for Telegram channel_post updates.

    PTB versions differ in whether CommandHandler checks channel_post
    updates.  This table lets the same decorated handlers run in channels
    when the normal CommandHandler does not claim the update.
    """
    handlers = {
        "start": start_cmd,
        "help": help_cmd,
        "menu": menu_cmd,
        "ping": ping_cmd,
        "myid": myid,
        "stopnc": stopnc,
        "spam1": spam1_cmd,
        "spam2": spam2_cmd,
        "spam3": spam3_cmd,
        "spam4": spam4_cmd,
        "stopspam1": stopspam1_cmd,
        "stopspam2": stopspam2_cmd,
        "stopspam3": stopspam3_cmd,
        "stopspam4": stopspam4_cmd,
        "pfp": pfp_cmd,
        "dps": dps_cmd,
        "ps": ps_cmd,
        "pfs": pfs_cmd,
        "mylund": addsudo,
        "dlund": delsudo,
        "lund": listsudo,
        "delay": delay_cmd,
        "status": status_cmd,
        "stopall": stopall,
        "purge": purge_cmd,
        "purgeme": purgeme_cmd,
        "mute": mute_cmd,
        "unmute": unmute_cmd,
        "lock": lock_cmd,
        "unlock": unlock_cmd,
        "promoteallbots": promoteallbots_cmd,
        "leavebot": leavebot_cmd,
        "gameover": gameover_cmd,
        "stopkknc": stopkknc,
        "stopkkspam": stopkkspam,
    }
    handlers.update({f"nc{i}": globals()[f"nc{i}_cmd"] for i in range(1, 11)})
    handlers.update({f"slide{i}": _slide_command_map[i] for i in range(1, 11)})
    handlers.update({
        f"stopslide{i}": _stopslide_command_map[i] for i in range(1, 11)
    })
    handlers.update(_kk_nc_cmds)
    handlers.update(_kk_spam_cmds)
    return handlers


_CHANNEL_COMMAND_HANDLERS = _build_channel_command_handlers()


async def channel_command_handler(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Fallback dispatcher for commands contained in channel posts."""
    message = getattr(update, "channel_post", None) or getattr(
        update, "effective_message", None
    )
    if not message:
        return
    text = (getattr(message, "text", None) or "").strip()
    match = re.match(r"^/([A-Za-z0-9_]+)(?:@([A-Za-z0-9_]+))?(?:\s+(.*))?$", text, re.S)
    if not match:
        return

    command, addressed_bot, argument_text = match.groups()
    if addressed_bot:
        bot_username = (getattr(context.bot, "username", None) or "").casefold()
        if bot_username and addressed_bot.casefold() != bot_username:
            return
    handler = _CHANNEL_COMMAND_HANDLERS.get(command.casefold())
    if handler is None:
        return

    # MessageHandler does not populate context.args; use the same whitespace
    # argument semantics as CommandHandler before invoking the shared handler.
    context.args = argument_text.split() if argument_text else []
    await handler(update, context)


