#              MAIN — KENTO BOT RUNNER
# ═══════════════════════════════════════════════
async def main():
    global apps, bots

    if not _guard_check():
        print(_LOCK_MSG)
        return

    valid_tokens = [t.strip() for t in TOKENS if t.strip()]
    if not valid_tokens:
        print("[SHIVAM ERROR] No tokens configured. Add your bot tokens to the TOKENS list.")
        return

    seen_tokens = set()
    for token in valid_tokens:
        if token in seen_tokens:
            print(f"[SHIVAM SKIP] Duplicate token skipped.")
            continue
        seen_tokens.add(token)
        try:
            app = Application.builder().token(token).build()

            app.add_handler(CommandHandler("start", start_cmd))
            app.add_handler(CommandHandler("help", help_cmd))
            app.add_handler(CommandHandler("menu", menu_cmd))
            app.add_handler(CommandHandler("ping", ping_cmd))
            app.add_handler(CommandHandler("myid", myid))

            app.add_handler(CommandHandler("nc1",  nc1_cmd))
            app.add_handler(CommandHandler("nc2",  nc2_cmd))
            app.add_handler(CommandHandler("nc3",  nc3_cmd))
            app.add_handler(CommandHandler("nc4",  nc4_cmd))
            app.add_handler(CommandHandler("nc5",  nc5_cmd))
            app.add_handler(CommandHandler("nc6",  nc6_cmd))
            app.add_handler(CommandHandler("nc7",  nc7_cmd))
            app.add_handler(CommandHandler("nc8",  nc8_cmd))
            app.add_handler(CommandHandler("nc9",  nc9_cmd))
            app.add_handler(CommandHandler("nc10", nc10_cmd))
            app.add_handler(CommandHandler("stopnc", stopnc))

            app.add_handler(CommandHandler("spam1", spam1_cmd))
            app.add_handler(CommandHandler("spam2", spam2_cmd))
            app.add_handler(CommandHandler("spam3", spam3_cmd))
            app.add_handler(CommandHandler("spam4", spam4_cmd))
            app.add_handler(CommandHandler("stopspam1", stopspam1_cmd))
            app.add_handler(CommandHandler("stopspam2", stopspam2_cmd))
            app.add_handler(CommandHandler("stopspam3", stopspam3_cmd))
            app.add_handler(CommandHandler("stopspam4", stopspam4_cmd))

            app.add_handler(CommandHandler("pfp", pfp_cmd))
            app.add_handler(CommandHandler("dps", dps_cmd))
            app.add_handler(CommandHandler("ps",  ps_cmd))
            app.add_handler(CommandHandler("pfs", pfs_cmd))

            app.add_handler(CommandHandler("mylund",  addsudo))
            app.add_handler(CommandHandler("dlund",  delsudo))
            app.add_handler(CommandHandler("lund", listsudo))

            app.add_handler(CommandHandler("delay",  delay_cmd))
            app.add_handler(CommandHandler("status", status_cmd))
            app.add_handler(CommandHandler("stopall", stopall))
            app.add_handler(CommandHandler("purge", purge_cmd))
            app.add_handler(CommandHandler("purgeme", purgeme_cmd))

            

            # All slide commands (1–10), including the six formerly missing
            # slide1–slide10 handlers and their stop commands.
            for _slide_num in range(1, 11):
                app.add_handler(
                    CommandHandler(
                        f"slide{_slide_num}",
                        _slide_command_map[_slide_num],
                    )
                )
                app.add_handler(
                    CommandHandler(
                        f"stopslide{_slide_num}",
                        _stopslide_command_map[_slide_num],
                    )
                )


          # Group admin commands (8 new from kk.py)
            app.add_handler(CommandHandler("mute", mute_cmd))
            app.add_handler(CommandHandler("unmute", unmute_cmd))
            app.add_handler(CommandHandler("lock", lock_cmd))
            app.add_handler(CommandHandler("unlock", unlock_cmd))
            app.add_handler(CommandHandler("promoteallbots", promoteallbots_cmd))
            app.add_handler(CommandHandler("leavebot", leavebot_cmd))
            app.add_handler(CommandHandler("gameover", gameover_cmd))

            # Named NC commands (52 from kk.py)
            for _nc_name in _kk_nc_cmds:
                app.add_handler(CommandHandler(_nc_name, _kk_nc_cmds[_nc_name]))
            app.add_handler(CommandHandler("stopkknc", stopkknc))

            # Named spam commands (19 from kk.py)
            for _spam_name in _kk_spam_cmds:
                app.add_handler(CommandHandler(_spam_name, _kk_spam_cmds[_spam_name]))
            app.add_handler(CommandHandler("stopkkspam", stopkkspam))
            # PTB 20.7 normally handles channel posts through CommandHandler,
            # but keep this fallback for channel_post updates on versions or
            # filters that only expose them to MessageHandler.
            app.add_handler(
                MessageHandler(
                    filters.UpdateType.CHANNEL_POST & filters.COMMAND,
                    channel_command_handler,
                ),
                group=0,
            )
            app.add_handler(ChatMemberHandler(autoremove_handler, ChatMemberHandler.CHAT_MEMBER))
            # Run before command handlers too, so a target's NEXT message
            # (text, command, photo, sticker, etc.) immediately becomes the
            # new slide reply anchor.
            app.add_handler(MessageHandler(filters.ALL, message_handler), group=-1)

            apps.append(app)
            bots.append(app.bot)
            print(f"[SHIVAM OK] Bot loaded: ...{token[-15:]}")
        except Exception as e:
            print(f"[SHIVAM ERROR] Failed to load token: {e}")

    if not apps:
        print("[SHIVAM ERROR] No bots started.")
        return

    print(f"[SHIVAM START] Running {len(apps)} bot(s)...")

    for app in apps:
        await app.initialize()
        await app.start()
        await app.updater.start_polling(drop_pending_updates=True)
        try:
            me = await app.bot.get_me()
            our_bot_ids.add(me.id)
        except Exception:
            pass

    print(f"[SHIVAM READY] All {len(apps)} bot(s) polling. Bot IDs: {our_bot_ids}")

    try:
        await asyncio.sleep(float("inf"))
    except (asyncio.CancelledError, KeyboardInterrupt):
        pass
    finally:
        for app in apps:
            try:
                await app.updater.stop()
                await app.stop()
                await app.shutdown()
            except Exception:
                pass



class HyperRateLimiter:
    """Cooperative, monotonic per-key limiter for Telegram API operations."""
    def __init__(self, interval: float = 0.01):
        self.interval = max(0.01, float(interval))
        self._last: Dict[object, float] = {}
        self._locks: Dict[object, asyncio.Lock] = {}

    async def wait(self, key="default"):
        lock = self._locks.setdefault(key, asyncio.Lock())
        async with lock:
            now = time.monotonic()
            remaining = self.interval - (now - self._last.get(key, 0.0))
            if remaining > 0:
                await asyncio.sleep(remaining)
            self._last[key] = time.monotonic()
            # Keep long-running bots from retaining one lock/timestamp per
            # transient chat forever.
            if len(self._last) > 2048:
                cutoff = time.monotonic() - max(self.interval * 1, 60.0)
                for old_key, timestamp in list(self._last.items()):
                    if timestamp < cutoff and old_key != key:
                        self._last.pop(old_key, None)
                        self._locks.pop(old_key, None)

    def reset(self, key=None):
        if key is None:
            self._last.clear()
            self._locks.clear()
        else:
            self._last.pop(key, None)
            self._locks.pop(key, None)


class FastLoopEngine:
    """Safe cooperative loop helper; never bypasses rate limits."""
    @staticmethod
    async def sleep(delay: float = 0.01):
        await asyncio.sleep(max(0.01, float(delay)))

    async def run_once(self, callback, *args, **kwargs):
        if not callable(callback):
            raise TypeError("callback must be callable")
        return await callback(*args, **kwargs)


class AttackController:
    """Serialize and rate-limit one operation per logical key."""
    def __init__(self, limiter=None):
        self.limiter = limiter or HyperRateLimiter()
        self._locks: Dict[object, asyncio.Lock] = {}

    async def run_once(self, callback, key="default", *args, **kwargs):
        if not callable(callback):
            raise TypeError("callback must be callable")
        lock = self._locks.setdefault(key, asyncio.Lock())
        try:
            async with lock:
                await self.limiter.wait(key)
                return await callback(*args, **kwargs)
        finally:
            if self._locks.get(key) is lock and not lock.locked():
                self._locks.pop(key, None)


class _HyperfireEngine:
    """Non-burst compatibility engine for a single cooperative operation."""
    def __init__(self, controller=None):
        self.controller = controller or AttackController()

    async def fire_once(self, callback, key="default", *args, **kwargs):
        return await self.controller.run_once(callback, key, *args, **kwargs)


_hyperfire_engine = _HyperfireEngine()

if __name__ == "__main__":
    asyncio.run(main())
